insert into public.questions (id, topic_id, kind, prompt, passage, choices, answer_index, answer_explanation, difficulty, source_name, source_url, license)
values ('starter-cars-passages-4', 'cars-passages', 'mcq', 'In the passage, the ''filter'' refers to:', 'Each generation of listeners seems certain that music was better when they were young. Critics often dismiss this as simple nostalgia, but the explanation may be partly statistical. The songs that survive from any decade are a small, filtered sample: the ones that were good enough, or lucky enough, to keep being played. Listeners compare that curated past with the unfiltered present, where the forgettable majority has not yet been forgotten. The comparison is unfair in a way that no amount of taste can correct. This does not mean that all eras are equal; some periods may genuinely have fostered more innovation, through new instruments, new recording technology, or new audiences. But claims about a golden age should be made with the filter in mind. A fair test would compare the past''s survivors with the present''s future survivors, an experiment we can only finish decades from now.', '["Listeners'' preference for familiar songs","The process by which only some songs keep being played over time","Recording technology that removes noise","Critics'' published reviews"]'::jsonb, 1, 'The filtered sample is ''the ones that were good enough, or lucky enough, to keep being played.''', 2, 'MedAi question bank (draft)', null, 'Original MedAi content. Draft, not yet reviewed.')
on conflict (id) do update set prompt = excluded.prompt, passage = excluded.passage, choices = excluded.choices,
  answer_index = excluded.answer_index, answer_explanation = excluded.answer_explanation,
  source_name = excluded.source_name, source_url = excluded.source_url, license = excluded.license
  where not public.questions.reviewed;
insert into public.questions (id, topic_id, kind, prompt, passage, choices, answer_index, answer_explanation, difficulty, source_name, source_url, license)
values ('starter-cars-passages-5', 'cars-passages', 'mcq', 'How would the author most likely respond to the claim that music from the 1970s was better than today''s?', 'Each generation of listeners seems certain that music was better when they were young. Critics often dismiss this as simple nostalgia, but the explanation may be partly statistical. The songs that survive from any decade are a small, filtered sample: the ones that were good enough, or lucky enough, to keep being played. Listeners compare that curated past with the unfiltered present, where the forgettable majority has not yet been forgotten. The comparison is unfair in a way that no amount of taste can correct. This does not mean that all eras are equal; some periods may genuinely have fostered more innovation, through new instruments, new recording technology, or new audiences. But claims about a golden age should be made with the filter in mind. A fair test would compare the past''s survivors with the present''s future survivors, an experiment we can only finish decades from now.', '["Agree, because older music was more innovative","Point out that the claim compares the past''s best songs with all of today''s songs","Insist that all musical eras are exactly equal","Deny that nostalgia exists"]'::jsonb, 1, 'The author''s central point is that the ''curated past'' is compared with the ''unfiltered present.'' The author also says ''this does not mean that all eras are equal.''', 2, 'MedAi question bank (draft)', null, 'Original MedAi content. Draft, not yet reviewed.')
